insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_6_v1'
from (values
('114.44.c.1.A',4,'At Level VI, speakers keep an appropriate tone while talking about past events, current events and future plans. The qualifier mostly consistent means the register is:','["usually appropriate with occasional lapses", "unrelated to the listener", "always perfect", "never appropriate"]'::jsonb,0,'Level VI register is mostly, not completely, consistent.','original'),
('114.44.c.1.A',4,'Which skill is expected of a Level VI speaker in conversation?','["speaking only about the present", "handling all time frames with a suitable register", "relying only on memorized phrases", "answering only yes or no"]'::jsonb,1,'Advanced conversation spans all time frames.','original'),
('114.44.c.1.B',4,'A student explains a scientific process and then a geographic trend in conversation. This shows ability to:','["recite one script", "avoid abstract topics", "exchange information across varied topics", "use only greetings"]'::jsonb,2,'Level VI handles geographic, scientific and other topics.','original'),
('114.44.c.1.B',4,'Which topic range fits Level VI verbal exchange?','["only names and ages", "only colors", "only weather words", "geographic, scientific and cultural subjects"]'::jsonb,3,'Advanced exchange spans many fields.','original'),
('114.44.c.1.C',4,'A formal letter with some elaboration, written across time frames, demonstrates:','["writing with mostly consistent register", "a text message only", "a single sentence", "a shopping list"]'::jsonb,0,'Elaborated correspondence shows advanced writing.','original'),
('114.44.c.1.C',4,'Which of these written items shows elaboration at Level VI?','["a single word reply", "a cover letter explaining background and goals", "a short caption", "a list of nouns"]'::jsonb,1,'Elaboration adds context and detail.','original'),
('114.44.c.1.D',4,'Producing written exchanges that provide information on varied topics with mostly consistent register means the writer:','["copies other texts", "avoids detail", "adapts tone to the reader while informing", "uses the same slang for everyone"]'::jsonb,2,'Written exchange fits the reader.','original'),
('114.44.c.1.D',4,'Which written exchange would meet the Level VI standard?','["a doodle", "a one-word chat message", "a list of random words", "a formal email reply that informs a client with clear detail"]'::jsonb,3,'Formal informative exchanges show advanced writing.','original'),
('114.44.c.2.A',4,'To appraise information from authentic print and electronic resources, a learner must:','["evaluate its quality, purpose and perspective", "accept every claim", "ignore the source", "skim only the headline"]'::jsonb,0,'Appraisal means evaluating.','original'),
('114.44.c.2.A',4,'Which of these is an authentic resource an advanced learner could appraise?','["a worksheet with blanks", "an editorial or an artwork review from the target culture", "a sticker sheet", "a vocabulary flashcard"]'::jsonb,1,'Authentic resources are made for speakers.','original'),
('114.44.c.2.B',4,'Appraising cultural practices and perspectives from authentic sources involves:','["counting words", "skipping context", "comparing, contrasting and judging significance", "copying quotes"]'::jsonb,2,'Appraisal adds judgment to comparison.','original'),
('114.44.c.2.B',4,'Why might two authentic sources appraise the same custom differently?','["they are the same length", "they use different fonts", "they were printed on paper", "their authors hold different perspectives"]'::jsonb,3,'Perspectives shape appraisal.','original'),
('114.44.c.2.C',4,'Listening to appraise an authentic broadcast means a learner:','["evaluates the speaker''s claims and tone", "ignores the content", "mutes the audio", "only counts the words"]'::jsonb,0,'Appraisal requires evaluation.','original'),
('114.44.c.2.C',4,'Which source is suitable for appraising authentic audio?','["a blank track", "a news interview made for native-speaking audiences", "a printed list", "a muted cartoon"]'::jsonb,1,'Authentic audio is made for speakers.','original'),
('114.44.c.2.D',4,'An advanced learner compares how two documentaries portray the same tradition and judges which is more balanced. This is:','["summarizing without thought", "copying vocabulary", "appraising cultural perspectives", "skipping the content"]'::jsonb,2,'Appraisal includes judgment.','original'),
('114.44.c.2.D',4,'When appraising perspectives in audiovisual sources, a learner should look at:','["only the volume", "only the length", "only the file type", "who made the source and why"]'::jsonb,3,'Authorship and purpose matter.','original'),
('114.44.c.3.A',4,'A Level VI presenter plans, produces and presents a talk with mostly consistent ease and clarity. This shows:','["strong presentational speaking", "random speech", "silent reading", "copying notes aloud"]'::jsonb,0,'Presentations are planned and delivered clearly.','original'),
('114.44.c.3.A',4,'Which action best improves a spoken presentation''s clarity?','["avoiding the audience", "organizing ideas and rehearsing delivery", "reading a script fast", "skipping preparation"]'::jsonb,1,'Planning and rehearsal improve clarity.','original'),
('114.44.c.3.B',4,'Planning and producing a written presentational communication with mostly consistent ease means the writer:','["uses only fragments", "copies another paper", "drafts and revises for clear expression", "writes without a plan"]'::jsonb,2,'Clear writing is revised.','original'),
('114.44.c.3.B',4,'Which written product is an advanced presentational communication?','["a list of nouns", "a doodle", "a text emoji", "a well-organized article on a social issue"]'::jsonb,3,'Articles present ideas to an audience.','original'),
('114.45.c.1.A',5,'A Level VII speaker engages in conversations with consistent register in all time frames. Consistent register means the speaker:','["reliably adjusts tone to listener and setting", "uses the same slang everywhere", "changes tone at random", "avoids all formality"]'::jsonb,0,'Consistency is the Level VII benchmark.','original'),
('114.45.c.1.A',5,'Which marks the difference between Level VI and Level VII conversation?','["simpler vocabulary", "register that is consistent rather than mostly consistent", "fewer topics", "shorter sentences"]'::jsonb,1,'Level VII is consistent.','original'),
('114.45.c.1.B',5,'Exchanging information on geographic, scientific, historical and cultural topics with consistent register requires:','["only gestures", "only silence", "wide vocabulary and precise tone control", "only common nouns"]'::jsonb,2,'Breadth and precision define Level VII.','original'),
('114.45.c.1.B',5,'A speaker moves from a casual talk to a formal debate about science policy while keeping appropriate tone. This is:','["inconsistent register", "avoidance of topic", "lack of control", "consistent register across contexts"]'::jsonb,3,'Register control across contexts.','original'),
('114.45.c.1.C',5,'Writing correspondence and reports with consistent register and elaboration shows:','["sophisticated written control", "copying", "basic note-taking", "guessing"]'::jsonb,0,'Elaboration with consistent register is advanced.','original'),
('114.45.c.1.C',5,'Which written product requires consistent register in all time frames?','["a list of nouns", "a formal report describing past findings and future plans", "a sticker label", "a single sentence"]'::jsonb,1,'Reports cover time frames.','original'),
('114.45.c.1.D',5,'Written exchanges that inform on a variety of topics with consistent register are expected to be:','["unrelated to the audience", "random and short", "clear, accurate and appropriate for the reader", "vague and casual"]'::jsonb,2,'Informative exchanges fit the reader.','original'),
('114.45.c.1.D',5,'Which written exchange best reflects Level VII?','["a scribble", "a quick meme", "a one-word reply", "a precise professional email that answers a complex inquiry"]'::jsonb,3,'Complex inquiries need precise replies.','original'),
('114.45.c.2.A',5,'To synthesize information from authentic print and electronic resources, a learner:','["combines ideas from several sources into a new understanding", "copies one source", "ignores differences", "reads only titles"]'::jsonb,0,'Synthesis integrates sources.','original'),
('114.45.c.2.A',5,'Which task is synthesis?','["copying a quote", "merging three articles'' findings into a single argument", "underlining one sentence", "counting pages"]'::jsonb,1,'Synthesis creates a unified view.','original'),
('114.45.c.2.B',5,'Synthesizing cultural practices and perspectives means:','["avoiding comparison", "listing facts only", "drawing connected conclusions from comparisons", "ignoring contrast"]'::jsonb,2,'Synthesis builds conclusions.','original'),
('114.45.c.2.B',5,'A student explains how three sources'' viewpoints on a tradition fit together. This is:','["skimming", "ignoring context", "copying text", "synthesizing cultural perspectives"]'::jsonb,3,'Synthesis weaves views together.','original'),
('114.45.c.2.C',5,'Listening to synthesize information from audio sources involves:','["integrating points from several recordings", "ignoring content", "muting the sound", "listening to one clip only"]'::jsonb,0,'Synthesis uses multiple sources.','original'),
('114.45.c.2.C',5,'Which task shows synthesis of audiovisual material?','["listing titles", "combining a documentary, an interview and a podcast into one analysis", "watching a clip silently", "copying credits"]'::jsonb,1,'Combining sources is synthesis.','original'),
('114.45.c.2.D',5,'Synthesizing cultural practices from authentic audiovisual resources leads a learner to:','["ignore the video", "copy the subtitles", "form a unified view of how practices relate to perspectives", "memorize one clip"]'::jsonb,2,'Synthesis connects practice and perspective.','original'),
('114.45.c.2.D',5,'Why synthesize rather than summarize a single source?','["it is shorter", "it avoids analysis", "it ignores evidence", "synthesis gives a broader, integrated understanding"]'::jsonb,3,'Synthesis integrates evidence.','original'),
('114.45.c.3.A',5,'A Level VII presenter plans and delivers a talk with consistent ease and clarity. This shows:','["polished presentational speaking", "reading blindly", "avoiding eye contact", "speaking off topic"]'::jsonb,0,'Consistent ease marks Level VII.','original'),
('114.45.c.3.A',5,'Which practice most strengthens a polished spoken presentation?','["speaking quickly", "tailoring structure and language to the audience", "using identical slides for every audience", "avoiding practice"]'::jsonb,1,'Audience awareness improves polish.','original'),
('114.45.c.3.B',5,'Producing a written presentational communication with consistent ease and clarity means:','["omitting structure", "writing once and submitting", "drafting, revising and editing until precise", "copying"]'::jsonb,2,'Precision comes from revision.','original'),
('114.45.c.3.B',5,'Which product reflects Level VII written presentation?','["an emoji", "a doodle", "a list of words", "a cohesive essay with a thesis and evidence"]'::jsonb,3,'Essays present complex ideas.','original'),
('114.46.c.1.A',4,'In a seminar, a student drafts a researchable question with the instructor''s guidance. A researchable question is one that:','["can be investigated with evidence", "has no possible answer", "is unrelated to the topic", "is purely opinion"]'::jsonb,0,'Research needs a question evidence can answer.','original'),
('114.46.c.1.A',4,'Which question is researchable?','["What is the best color?", "How have social media changed communication in Spanish-speaking communities?", "Why is it good?", "Is it nice?"]'::jsonb,1,'Researchable questions are specific and evidence-based.','original'),
('114.46.c.1.B',4,'Communicating with accuracy and fluency to participate fully in conversations means a student:','["reads from notes only", "speaks very slowly", "expresses ideas clearly and correctly in real time", "avoids complex topics"]'::jsonb,2,'Fluency and accuracy together.','original'),
('114.46.c.1.B',4,'Which scenario shows full participation in a seminar conversation?','["reciting memorized text", "staying silent", "interrupting without listening", "building on others'' points with accurate language"]'::jsonb,3,'Full participation involves responding.','original'),
('114.46.c.1.C',4,'Comprehending language from within the cultural framework includes understanding:','["nuance, subtlety and cultural references", "only grammar tables", "only literal word meanings", "only spelling"]'::jsonb,0,'Cultural framework adds meaning.','original'),
('114.46.c.1.C',4,'Why does nuance matter when interpreting authentic speech?','["only grammar matters", "tone and cultural context can change meaning", "context is irrelevant", "words never change"]'::jsonb,1,'Nuance depends on culture.','original'),
('114.46.c.1.D',4,'Producing both formal and informal correspondence on varied topics requires the writer to:','["avoid greetings", "use one style for all", "choose style and register to fit the audience", "write in fragments"]'::jsonb,2,'Style matches reader.','original'),
('114.46.c.1.D',4,'Which pair shows formal and informal correspondence?','["two maps", "two grocery lists", "two math sheets", "a letter to a university and a note to a friend"]'::jsonb,3,'Correspondence varies by audience.','original'),
('114.46.c.1.E',4,'An in-depth research paper differs from a brief summary because it:','["analyzes sources and develops a supported argument", "lists a few facts only", "avoids sources", "repeats one sentence"]'::jsonb,0,'Research papers analyze and argue.','original'),
('114.46.c.1.E',4,'Which feature belongs in an in-depth report?','["only a list of words", "a thesis, evidence from several sources and a conclusion", "only pictures", "only a title"]'::jsonb,1,'Reports develop a thesis with evidence.','original'),
('114.46.c.1.F',4,'After completing research, a student poses new questions for further study. This shows:','["avoidance of the topic", "lack of interest", "reflection that leads to inquiry", "the end of learning"]'::jsonb,2,'Research opens new questions.','original'),
('114.46.c.1.F',4,'Which question follows from research findings about a language''s regional variation?','["Who won the match?", "What is two plus two?", "What is for lunch?", "How might regional variation affect communication in the workplace?"]'::jsonb,3,'Follow-up questions build on findings.','original'),
('114.46.c.2.A',4,'A seminar student collects political cartoons, paintings and media clips for a project. This is:','["gathering visual and media sources", "avoiding research", "writing without sources", "copying a classmate"]'::jsonb,0,'Visual sources support research.','original'),
('114.46.c.2.A',4,'Why include visual images such as photographs in a research portfolio?','["they have no value", "they offer evidence and perspective beyond text", "they replace all reading", "they hide meaning"]'::jsonb,1,'Images provide evidence.','original'),
('114.46.c.2.B',4,'Compiling written ideas and representations means:','["discarding drafts", "copying a book", "organizing notes, drafts and sources together", "avoiding notes"]'::jsonb,2,'Compiling organizes work.','original'),
('114.46.c.2.B',4,'Which practice helps a student compile ideas for a project?','["scattering notes", "relying on memory only", "deleting sources", "keeping dated notes and drafts in one organized place"]'::jsonb,3,'Organization supports compiling.','original'),
('114.46.c.2.C',4,'To interpret information and draw conclusions from a wide range of sources, a student must:','["weigh evidence from several viewpoints", "avoid reading", "ignore conflicting data", "trust one source only"]'::jsonb,0,'Interpretation weighs evidence.','original'),
('114.46.c.2.C',4,'A conclusion is strongest when it is:','["based on one headline", "supported by evidence from multiple sources", "based on a guess", "unrelated to the data"]'::jsonb,1,'Conclusions need evidence.','original'),
('114.46.c.2.D',4,'Identifying bias in a news article involves noticing:','["the paper color", "the page number", "slanted wording or one-sided selection of facts", "the font size"]'::jsonb,2,'Bias appears in wording and selection.','original'),
('114.46.c.2.D',4,'Which indicates possible bias in a spoken report?','["citations to several viewpoints", "neutral wording", "a balanced list of sources", "loaded words that push one point of view"]'::jsonb,3,'Loaded language signals bias.','original'),
('114.46.c.2.E',4,'Using writing and speaking for reflection and exploration means the student:','["thinks through ideas by writing and discussing", "copies a text", "memorizes only", "avoids reflection"]'::jsonb,0,'Reflection builds understanding.','original'),
('114.46.c.2.E',4,'Which activity supports reflection?','["copying a classmate", "keeping a learning journal about discoveries and questions", "skipping notes", "avoiding discussion"]'::jsonb,1,'Journals encourage reflection.','original'),
('114.46.c.2.F',4,'Citing sources appropriately in a research project:','["hides the source", "is optional for all work", "gives credit and lets readers verify information", "reduces credibility"]'::jsonb,2,'Citations give credit and enable checking.','original'),
('114.46.c.2.F',4,'Which is an appropriate citation practice?','["omitting authors", "copying without credit", "citing only one of five sources", "listing the author, title and source of every reference used"]'::jsonb,3,'Complete citations credit sources.','original'),
('114.46.c.2.G',4,'A seminar portfolio is best described as:','["a collection of work showing a student''s learning and growth", "a grade report", "a set of unrelated files", "a single worksheet"]'::jsonb,0,'Portfolios gather evidence of learning.','original'),
('114.46.c.2.G',4,'Presenting a portfolio requires the student to:','["read it silently", "organize work and explain what it shows", "hand in blank pages", "avoid explaining"]'::jsonb,1,'Presentation includes explanation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
